SELECT CASE WHEN unit_price >= 410 THEN 'high' WHEN unit_price >= 90 THEN 'mid' ELSE 'low' END AS unit_price_bucket, product_id, CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END AS quantity_bucket, COUNT(unit_price) AS unit_price_count FROM order_items WHERE (quantity > 6 AND product_id IN (21, 34)) OR quantity <= 3 GROUP BY unit_price_bucket, product_id, quantity_bucket ORDER BY unit_price_bucket, 4, product_id, quantity_bucket LIMIT 5;
